1	/**
2	 * cf-extra-routes.ts
3	 *
4	 * CF-native handlers for API endpoints that use raw Express handlers in the
5	 * server package (making them invisible to extractRoutesFromRouter) or depend
6	 * on runtime registries (adapters, plugins) that don't exist in a CF Worker.
7	 *
8	 * Registered in app.ts BEFORE the /api/* catch-all so they shadow the 501.
9	 */
10	
11	import type { Hono } from "hono";
12	import { and, asc, desc, eq, inArray } from "drizzle-orm";
13	import {
14	  agents,
15	  authUsers,
16	  companyMemberships,
17	  companySkills,
18	  invites,
19	  joinRequests,
20	} from "@paperclipai/db";
21	import { collapseDuplicatePendingHumanJoinRequests } from "../../../../server/src/lib/join-request-dedupe.js";
22	import { resolveHumanInviteRole } from "../../../../server/src/services/company-member-roles.js";
23	import { createHyperdriveDb } from "../db/hyperdrive.js";
24	import type { Env } from "./env.js";
25	
26	// ---------------------------------------------------------------------------
27	// Helpers (inlined from server/src/routes/access.ts — CF-safe subsets)
28	// ---------------------------------------------------------------------------
29	
30	function extractInviteMessage(invite: {
31	  defaultsPayload: unknown;
32	}): string | null {
33	  const raw = invite.defaultsPayload;
34	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
35	  const msg = (raw as Record<string, unknown>).agentMessage;
36	  if (typeof msg !== "string") return null;
37	  const trimmed = msg.trim();
38	  return trimmed.length ? trimmed : null;
39	}
40	
41	type SkillSourceBadge = "paperclip" | "skills_sh" | "github" | "url" | "local" | "catalog";
42	
43	function deriveSkillSource(skill: {
44	  sourceType: string;
45	  sourceLocator: string | null;
46	  metadata: unknown;
47	}): {
48	  editable: boolean;
49	  editableReason: string | null;
50	  sourceLabel: string | null;
51	  sourceBadge: SkillSourceBadge;
52	  sourcePath: null;
53	} {
54	  const meta =
55	    skill.metadata && typeof skill.metadata === "object" && !Array.isArray(skill.metadata)
56	      ? (skill.metadata as Record<string, unknown>)
57	      : {};
58	
59	  if (meta.sourceKind === "paperclip_bundled") {
60	    return { editable: false, editableReason: "Bundled Paperclip skills are read-only.", sourceLabel: "Paperclip bundled", sourceBadge: "paperclip", sourcePath: null };
61	  }
62	  if (skill.sourceType === "skills_sh") {
63	    return { editable: false, editableReason: "Skills.sh-managed skills are read-only.", sourceLabel: skill.sourceLocator, sourceBadge: "skills_sh", sourcePath: null };
64	  }
65	  if (skill.sourceType === "github") {
66	    const owner = typeof meta.owner === "string" ? meta.owner : null;
67	    const repo = typeof meta.repo === "string" ? meta.repo : null;
68	    return { editable: false, editableReason: "Remote GitHub skills are read-only.", sourceLabel: owner && repo ? `${owner}/${repo}` : skill.sourceLocator, sourceBadge: "github", sourcePath: null };
69	  }
70	  if (skill.sourceType === "url") {
71	    return { editable: false, editableReason: "URL-based skills are read-only.", sourceLabel: skill.sourceLocator, sourceBadge: "url", sourcePath: null };
72	  }
73	  if (skill.sourceType === "local_path") {
74	    return { editable: true, editableReason: null, sourceLabel: skill.sourceLocator, sourceBadge: "local", sourcePath: null };
75	  }
76	  return { editable: false, editableReason: "This skill source is read-only.", sourceLabel: skill.sourceLocator, sourceBadge: "catalog", sourcePath: null };
77	}
