79	// ---------------------------------------------------------------------------
80	// Route registration
81	// ---------------------------------------------------------------------------
82	
83	export function registerCfExtraRoutes(app: Hono<{ Bindings: Env }>): void {
84	  // -------------------------------------------------------------------------
85	  // GET /api/adapters — no adapter registry in CF Workers
86	  // -------------------------------------------------------------------------
87	  app.get("/api/adapters", (c) => c.json([]));
88	
89	  // -------------------------------------------------------------------------
90	  // GET /api/plugins — no plugin registry in CF Workers
91	  // GET /api/plugins/ui-contributions — no plugin registry in CF Workers
92	  // -------------------------------------------------------------------------
93	  app.get("/api/plugins", (c) => c.json([]));
94	  app.get("/api/plugins/ui-contributions", (c) => c.json([]));
95	
96	  // -------------------------------------------------------------------------
97	  // GET /api/companies/:companyId/skills
98	  //
99	  // Mirrors companySkillService.list() but skips ensureSkillInventoryCurrent
100	  // (which uses node:fs) since CF Workers have no host filesystem.
101	  // -------------------------------------------------------------------------
102	  app.get("/api/companies/:companyId/skills", async (c) => {
103	    const companyId = c.req.param("companyId");
104	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
105	
106	    const rows = await db
107	      .select({
108	        id: companySkills.id,
109	        companyId: companySkills.companyId,
110	        key: companySkills.key,
111	        slug: companySkills.slug,
112	        name: companySkills.name,
113	        description: companySkills.description,
114	        sourceType: companySkills.sourceType,
115	        sourceLocator: companySkills.sourceLocator,
116	        sourceRef: companySkills.sourceRef,
117	        trustLevel: companySkills.trustLevel,
118	        compatibility: companySkills.compatibility,
119	        fileInventory: companySkills.fileInventory,
120	        metadata: companySkills.metadata,
121	        createdAt: companySkills.createdAt,
122	        updatedAt: companySkills.updatedAt,
123	      })
124	      .from(companySkills)
125	      .where(eq(companySkills.companyId, companyId))
126	      .orderBy(asc(companySkills.name), asc(companySkills.key));
127	
128	    // attachedAgentCount: resolveDesiredSkillKeys uses non-exported internals;
129	    // query agents and do a simple adapterConfig scan instead.
130	    const agentRows = await db
131	      .select({ adapterConfig: agents.adapterConfig })
132	      .from(agents)
133	      .where(eq(agents.companyId, companyId));
134	
135	    const result = rows.map((row) => {
136	      const source = deriveSkillSource({
137	        sourceType: row.sourceType,
138	        sourceLocator: row.sourceLocator ?? null,
139	        metadata: row.metadata,
140	      });
141	
142	      const attachedAgentCount = agentRows.filter((agent) => {
143	        const cfg = agent.adapterConfig;
144	        if (!cfg || typeof cfg !== "object" || Array.isArray(cfg)) return false;
145	        const skillsValue = (cfg as Record<string, unknown>).skills;
146	        if (!Array.isArray(skillsValue)) return false;
147	        return skillsValue.some(
148	          (entry) =>
149	            (typeof entry === "string" && entry === row.key) ||
150	            (entry && typeof entry === "object" && (entry as Record<string, unknown>).key === row.key),
151	        );
152	      }).length;
153	
154	      return {
155	        id: row.id,
156	        companyId: row.companyId,
157	        key: row.key,
158	        slug: row.slug,
159	        name: row.name,
160	        description: row.description ?? null,
161	        sourceType: row.sourceType,
162	        sourceLocator: row.sourceLocator ?? null,
163	        sourceRef: row.sourceRef ?? null,
164	        trustLevel: row.trustLevel,
165	        compatibility: row.compatibility,
166	        fileInventory: Array.isArray(row.fileInventory) ? row.fileInventory : [],
167	        metadata: row.metadata ?? null,
168	        createdAt: row.createdAt,
169	        updatedAt: row.updatedAt,
170	        attachedAgentCount,
171	        ...source,
172	      };
173	    });
174	
175	    return c.json(result);
176	  });
