178	  // -------------------------------------------------------------------------
179	  // GET /api/companies/:companyId/join-requests
180	  // -------------------------------------------------------------------------
181	  app.get("/api/companies/:companyId/join-requests", async (c) => {
182	    const companyId = c.req.param("companyId");
183	    const statusFilter = c.req.query("status");
184	    const requestTypeFilter = c.req.query("requestType");
185	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
186	
187	    const allRows = await db
188	      .select()
189	      .from(joinRequests)
190	      .where(eq(joinRequests.companyId, companyId))
191	      .orderBy(desc(joinRequests.createdAt));
192	
193	    const rows = collapseDuplicatePendingHumanJoinRequests(allRows);
194	
195	    const inviteIds = [...new Set(rows.map((r) => r.inviteId))];
196	    const inviteRows = inviteIds.length
197	      ? await db.select().from(invites).where(inArray(invites.id, inviteIds))
198	      : [];
199	    const inviteMap = new Map(inviteRows.map((inv) => [inv.id, inv]));
200	
201	    const userIds = [
202	      ...new Set(
203	        [
204	          ...rows.map((r) => r.requestingUserId),
205	          ...rows.map((r) => r.approvedByUserId),
206	          ...rows.map((r) => r.rejectedByUserId),
207	          ...inviteRows.map((inv) => inv.invitedByUserId),
208	        ].filter((id): id is string => Boolean(id)),
209	      ),
210	    ];
211	    const userRows = userIds.length
212	      ? await db
213	          .select({ id: authUsers.id, email: authUsers.email, name: authUsers.name, image: authUsers.image })
214	          .from(authUsers)
215	          .where(inArray(authUsers.id, userIds))
216	      : [];
217	    const userMap = new Map(
218	      userRows.map((u) => [u.id, { id: u.id, email: u.email ?? null, name: u.name ?? null, image: u.image ?? null }]),
219	    );
220	
221	    const toUser = (id: string | null) => (id ? (userMap.get(id) ?? null) : null);
222	
223	    const filtered = rows
224	      .map((row) => {
225	        const { claimSecretHash: _ch, ...safe } = row;
226	        const inv = inviteMap.get(row.inviteId) ?? null;
227	        return {
228	          ...safe,
229	          requesterUser: toUser(row.requestingUserId),
230	          approvedByUser: toUser(row.approvedByUserId),
231	          rejectedByUser: toUser(row.rejectedByUserId),
232	          invite: inv
233	            ? {
234	                id: inv.id,
235	                inviteType: inv.inviteType,
236	                allowedJoinTypes: inv.allowedJoinTypes,
237	                humanRole: resolveHumanInviteRole(inv.defaultsPayload as Record<string, unknown> | null),
238	                inviteMessage: extractInviteMessage(inv),
239	                createdAt: inv.createdAt,
240	                expiresAt: inv.expiresAt,
241	                revokedAt: inv.revokedAt,
242	                acceptedAt: inv.acceptedAt,
243	                invitedByUser: toUser(inv.invitedByUserId),
244	              }
245	            : null,
246	        };
247	      })
248	      .filter((row) => {
249	        if (statusFilter && row.status !== statusFilter) return false;
250	        if (requestTypeFilter && row.requestType !== requestTypeFilter) return false;
251	        return true;
252	      });
253	
254	    return c.json(filtered);
255	  });
