257	  // -------------------------------------------------------------------------
258	  // GET /api/companies/:companyId/user-directory
259	  // -------------------------------------------------------------------------
260	  app.get("/api/companies/:companyId/user-directory", async (c) => {
261	    const companyId = c.req.param("companyId");
262	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
263	
264	    const members = await db
265	      .select({ principalId: companyMemberships.principalId, status: companyMemberships.status })
266	      .from(companyMemberships)
267	      .where(
268	        and(
269	          eq(companyMemberships.companyId, companyId),
270	          eq(companyMemberships.principalType, "user"),
271	          eq(companyMemberships.status, "active"),
272	        ),
273	      )
274	      .orderBy(desc(companyMemberships.updatedAt));
275	
276	    const userIds = [...new Set(members.map((m) => m.principalId))];
277	    const userRows = userIds.length
278	      ? await db
279	          .select({ id: authUsers.id, email: authUsers.email, name: authUsers.name, image: authUsers.image })
280	          .from(authUsers)
281	          .where(inArray(authUsers.id, userIds))
282	      : [];
283	    const userMap = new Map(
284	      userRows.map((u) => [u.id, { id: u.id, email: u.email ?? null, name: u.name ?? null, image: u.image ?? null }]),
285	    );
286	
287	    const users = members.map((m) => ({
288	      principalId: m.principalId,
289	      status: "active" as const,
290	      user: userMap.get(m.principalId) ?? null,
291	    }));
292	
293	    return c.json({ users });
294	  });
295	
296	  // -------------------------------------------------------------------------
297	  // GET /api/companies/:companyId/events/ws
298	  //
299	  // CF-native WebSocket upgrade. Without a Durable Object pub/sub bus, the
300	  // connection stays open but receives no server-sent events. The frontend
301	  // treats this as a connected (but silent) event stream, which is better
302	  // than a hard error.
303	  // -------------------------------------------------------------------------
304	  app.get("/api/companies/:companyId/events/ws", (c) => {
305	    const upgrade = c.req.header("Upgrade");
306	    if (!upgrade || upgrade.toLowerCase() !== "websocket") {
307	      return c.text("Expected WebSocket upgrade", 426);
308	    }
309	    const { 0: client, 1: server } = new WebSocketPair();
310	    server.accept();
311	    server.addEventListener("message", () => { /* no-op: no pub/sub wired yet */ });
312	    return new Response(null, { status: 101, webSocket: client });
313	  });
314	}
